{
  "name": "@d-ai/magpie",
  "version": "0.2.1",
  "description": "D.AI (dai.itbug.shop) chat models in magpie and OpenCode, plus a read-only image/video/audio model catalog",
  "type": "module",
  "main": "./index.mjs",
  "exports": {
    ".": "./index.mjs"
  },
  "files": [
    "index.mjs",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "magpie",
    "magpie-plugin",
    "dai",
    "d-ai"
  ],
  "license": "MIT",
  "homepage": "https://ai.itbug.shop",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mdddj/d-ai-magpie.git"
  },
  "magpie": {
    "maxConcurrency": 4,
    "icon": "data:image/svg+xml;base64,"
  },
  "publishConfig": {
    "access": "public"
  }
}

// D.AI (dai.itbug.shop) as a magpie / OpenCode provider plugin.
//
// A D.AI OAuth sign-in or API key (`ddsk_…`) signs an account in; magpie may
// hold several under the same provider. Models come from D.AI's public capability catalog
// (`GET /api/system/public/capability-docs`), narrowed to what the key may
// actually call (`GET /v1/models`). Chat models run on D.AI's
// OpenAI-compatible `/v1/chat/completions`, Claude models on `/v1/messages`.
// `auth.usage` reads the account behind the key (`GET /api/ai/account`): the
// wallet balance, the tier, and how much this key alone may spend.
//
// `auth.usage` reads `GET /api/ai/account`, which accepts both a `ddsk_` key
// and an OAuth access token with the `media` scope. The older JWT-only
// endpoints (`/api/usd/me`, `/api/user/usage-stats`) cannot serve a plugin,
// and the key's call log only counts calls, not money.
//
// Facts the tables below encode (checked 2026-10-22):
//   - The capability codes carrying token-metered chat are
//     `openai_chat_completions` (12 models) and `claude_messages` (5 models).
//   - `/v1/models` takes the API key as `Authorization: Bearer` or `x-api-key`
//     and lists only the models that key may use.
//   - `prepay_completion_token_limit` is D.AI's completion cap and the value a
//     client should send as its max output tokens (`sdks/pi/src/discover.ts`).
//   - Thinking levels and image input mirror `sdks/pi/src/thinking.ts`, the
//     only place these were verified against the upstreams behind D.AI. A model
//     absent from both tables is declared text-only without thinking levels
//     until someone checks it. D.AI's own catalog is not consulted for either:
//     it carries no per-model reasoning or modality metadata.
//
// OAuth uses the system browser with PKCE S256 and a loopback callback owned by
// this plugin. The refresh token stays in magpie's auth store; access tokens
// and their expiry are renewed by magpie before every request.
//
// The same module also gives a read-only media catalog tool. Magpie tools run
// from a separate MCP server and do not receive the provider account's key, so
// paid generation and account-scoped job tools are intentionally absent.
//
// Sections: constants · helpers · chat catalog · media catalog · plugin.

import { createHash, randomBytes } from "node:crypto";
import { createServer } from "node:http";

const PROVIDER = "dai";
const CLIENT = "magpie/0.2.1";
const DEFAULT_BASE = "https://dai.itbug.shop";
const OPENAI_NPM = "@ai-sdk/openai-compatible";
const ANTHROPIC_NPM = "@ai-sdk/anthropic";
const CATALOG_TTL_MS = 5 * 60 * 1000;
const REQUEST_TIMEOUT_MS = 20_000;
const MEDIA_CATALOG_LIMIT = 20;
const MEDIA_KINDS = new Set(["image", "video", "audio"]);
const OAUTH_CLIENT_ID = "ddc_i4mhCndrFLK3LAYBaK8d";
const OAUTH_SCOPES = "openid profile email offline_access media";
const OAUTH_CALLBACK_PATH = "/callback";
const OAUTH_SIGN_IN_TIMEOUT_MS = 5 * 60 * 1000;

/** Display names for the public tiers; unknown codes stay unchanged. */
const TIER_NAMES = {
	starter: "入门版",
	basic: "基础版",
	pro: "专业版",
	max: "旗舰版",
	trial: "试用用户",
};

/** Billing cycles as the usage card says them. */
const BILLING_CYCLES = {
	monthly: "月付",
	quarterly: "季付",
	semiannual: "半年付",
	annual: "年付",
};

/** Capability codes whose models are token-metered chat models. */
const CHAT_CAPABILITIES = new Set(["openai_chat_completions", "claude_messages"]);

/** The capability whose models answer System One questions, not conversations. */
const DECISION_CAPABILITY = "systemone_decision";

/**
 * Where magpie asks a provider's decision models: its base + `/systemone`,
 * which is `…/v1/systemone` for a provider on `/v1`. D.AI serves Jev at
 * `POST /api/ai/systemone/v1/decisions`, so the loader's fetch moves it there.
 */
const SYSTEMONE_PATH = "/v1/systemone";
const DECISION_ENDPOINT_PATH = "/api/ai/systemone/v1/decisions";

/** The capability D.AI serves on the OpenAI Images API. */
const IMAGE_CAPABILITY = "openai_image";

/** The capability D.AI serves at its own Seedance submit endpoint. */
const VIDEO_CAPABILITY = "seedance_video";
const SEEDANCE_SUBMIT_PATH = "/api/video/seedance/v1/generations";
const JOB_PATH = "/api/ai/jobs";
/** The resolutions D.AI prices apart, as its service codes end. */
const VIDEO_RESOLUTIONS = ["4k", "1080p", "720p", "480p"];
const DEFAULT_VIDEO_RESOLUTION = "720p";
/** OpenAI's `size` as Seedance's `ratio`. */
const VIDEO_RATIOS = {
	"1280x720": "16:9",
	"720x1280": "9:16",
	"1024x1024": "1:1",
	"1152x864": "4:3",
	"864x1152": "3:4",
	"1680x720": "21:9",
};

/**
 * magpie draws at its provider's base + `/images/…`; D.AI keeps those under
 * `/api/image/openai/v1`.
 */
const DAI_PATHS = new Map([
	[SYSTEMONE_PATH, DECISION_ENDPOINT_PATH],
	["/v1/images/generations", "/api/image/openai/v1/images/generations"],
	["/v1/images/edits", "/api/image/openai/v1/images/edits"],
]);

/** Thinking levels per model, verified against pi's tables. Absent = none offered. */
const VARIANTS = {
	// GPT-5.6: `off` is `none`, no `minimal`; the upstream takes the rest.
	"gpt-5.6-luna": ["none", "low", "medium", "high", "xhigh", "max"],
	"gpt-5.6-sol": ["none", "low", "medium", "high", "xhigh", "max"],
	"gpt-5.6-terra": ["none", "low", "medium", "high", "xhigh", "max"],
	// GPT-6 cannot turn thinking off.
	"gpt-6-astra": ["low", "medium", "high", "xhigh", "max"],
	"gpt-6-sol": ["low", "medium", "high", "xhigh", "max"],
	"gpt-6.1-sol": ["low", "medium", "high", "xhigh", "max"],
	// River rejects minimal, medium and xhigh on DeepSeek-V4.1-Flash; `none` is off.
	"deepseek-v4.1-flash": ["none", "low", "high", "max"],
	"deepseek-v4.1-flash-1017": ["none", "low", "high", "max"],
	// GLM-5.3-Flash cannot disable reasoning; River also rejects minimal/medium/xhigh.
	"glm-5.3-flash": ["low", "high", "max"],
	// Claude: the adaptive-effort models take xhigh/max, Opus 5.5 the full range.
	"claude-fable-5": ["xhigh", "max"],
	"claude-opus-4-7": ["xhigh", "max"],
	"claude-opus-4-8": ["xhigh", "max"],
	"claude-opus-5": ["xhigh", "max"],
	"claude-opus-5-5": ["low", "medium", "high", "xhigh", "max"],
};

/**
 * Models that take images as well as text. D.AI serves GPT-5/6, Claude,
 * DeepSeek and GLM with image input. Gemini and Grok are text-only through
 * this gateway until pi's modality table marks them otherwise.
 */
const VISION = /^(?:gpt-5|gpt-6|deepseek-|glm-|claude-)/u;

const FALLBACK_DECISIONS = [["jev", "Jev 决策"]];

/**
 * Offline fallback chat models, in the shape the network path builds, for a
 * magpie that cannot reach D.AI while the provider is first configured.
 * `[id, context, output, input USD/1M, output USD/1M, cache-read USD/1M]`.
 */
const FALLBACK_ROWS = [
	["deepseek-v4.1-flash", 1_048_576, 128_000, 0.15, 0.6, 0.003],
	["deepseek-v4.1-flash-1017", 1_048_576, 128_000, 0.15, 0.6, 0.003],
	["gemini-3.8-flash", 1_050_000, 128_000, 0.5, 3, 0.05],
	["glm-5.3-flash", 1_048_576, 128_000, 0.15, 0.5, 0.03],
	["gpt-5.6-luna", 1_050_000, 128_000, 0.2, 1.2, 0.02],
	["gpt-5.6-sol", 1_050_000, 128_000, 5, 30, 0.5],
	["gpt-5.6-terra", 1_050_000, 128_000, 2, 12, 0.2],
	["gpt-6-astra", 1_050_000, 128_000, 10, 50, 1],
	["gpt-6-sol", 1_050_000, 128_000, 2, 10, 0.2],
	["gpt-6.1-sol", 1_050_000, 128_000, 2, 10, 0.1],
	["grok-4.6", 500_000, 128_000, 1.5, 5, 0.4],
	["grok-4.7", 500_000, 128_000, 1.5, 5, 0.4],
	["claude-fable-5", 1_000_000, 128_000, 20, 100, 2],
	["claude-opus-4-7", 1_000_000, 128_000, 10, 50, 1],
	["claude-opus-4-8", 1_000_000, 128_000, 10, 50, 1],
	["claude-opus-5", 1_000_000, 128_000, 10, 50, 1],
	["claude-opus-5-5", 1_000_000, 128_000, 8, 40, 0.4],
];

// ---- helpers -------------------------------------------------------------------

const textOf = (value) => (typeof value === "string" && value.trim() ? value.trim() : "");
const numberOr = (value, fallback) =>
	typeof value === "number" && Number.isFinite(value) ? value : fallback;
const optionalNumber = (value) =>
	typeof value === "number" && Number.isFinite(value) ? value : undefined;
const positiveNumber = (value) =>
	typeof value === "number" && Number.isFinite(value) && value > 0 ? value : undefined;

/**
 * A USD amount as magpie's cards say one: whole dollars plain, otherwise the
 * significant decimals without a trail of zeros ($86.952653 -> "86.952653").
 * Six places is D.AI's scale, so nothing is rounded away that matters.
 */
function usd(value) {
	const n = Number(value);
	if (!Number.isFinite(n)) return "0";
	return n.toFixed(6).replace(/\.?0+$/u, "") || "0";
}

/** The base URL with no trailing slash and no trailing `/v1`. */
function normalizeBase(raw) {
	const value = textOf(raw);
	if (!value) return undefined;
	return value.replace(/\/+$/u, "").replace(/\/v1$/u, "");
}

const apiBase = (base) => `${base}/v1`;

const isClaudeModel = (id) => id.startsWith("claude-");

/** `ddsk_01ABC_secret` → what a card may show, never the secret itself. */
function keyLabel(key) {
	const id = textOf(key).replace(/^ddsk_/u, "").split("_")[0];
	return id ? `密钥 ${id}` : "API 密钥";
}

const isOAuthAuth = (auth) => auth?.type === "oauth";

/** The credential a signed-in account uses for D.AI requests. */
const credentialOf = (auth) =>
	isOAuthAuth(auth) ? textOf(auth.access) : textOf(auth?.key);

/** A label for a card when the account has no usable key prefix. */
function authLabel(auth) {
	if (!isOAuthAuth(auth)) return keyLabel(auth?.key);
	return textOf(auth.accountId) || "OAuth 登录";
}

const tierLabel = (code) => TIER_NAMES[textOf(code)] ?? textOf(code);
const cycleLabel = (cycle) => BILLING_CYCLES[textOf(cycle)] ?? textOf(cycle);
const statusLabel = (status) => {
	const value = textOf(status);
	return (
		{
			success: "成功",
			completed: "已完成",
			failed: "失败",
			processing: "处理中",
			pending: "等待中",
			cancelled: "已取消",
			canceled: "已取消",
			refunded: "已退款",
		}[value] ?? value
	);
};

function variantsOf(id) {
	const levels =
		VARIANTS[id] ??
		(/^gpt-5\.6/u.test(id)
			? VARIANTS["gpt-5.6-luna"]
			: /^gpt-6\.1/u.test(id)
				? VARIANTS["gpt-6.1-sol"]
				: /^gpt-6/u.test(id)
				? VARIANTS["gpt-6-astra"]
				: /^deepseek-v4\.1-flash/u.test(id)
					? VARIANTS["deepseek-v4.1-flash"]
					: undefined);
	if (!levels) return undefined;
	return Object.fromEntries(levels.map((level) => [level, {}]));
}

/**
 * An OpenCode `Model`, which is also what magpie's `config` hook wants. Both
 * `api` and `provider` are written because the two documents disagree on which
 * one carries a per-model API override; they hold the same values, so either
 * reader sees the same thing.
 */
function buildModel(id, base, rate = {}) {
	const rules = rate.billing_rules ?? {};
	const vision = VISION.test(id);
	const variants = variantsOf(id);
	const npm = isClaudeModel(id) ? ANTHROPIC_NPM : OPENAI_NPM;
	const cost = {
		input: numberOr(rate.input_usd_per_1m_tokens, 0),
		output: numberOr(rate.output_usd_per_1m_tokens, 0),
	};
	const cacheRead = cacheRate(id, rate);
	const cacheWrite = positiveNumber(rules.cache_write_usd_per_1m_tokens);
	if (cacheRead !== undefined) cost.cache_read = cacheRead;
	if (cacheWrite !== undefined) cost.cache_write = cacheWrite;
	// OpenCode reads the flat `cache_read` / `cache_write` above; magpie's
	// plugin reader looks under `cache.read` / `cache.write`, so it saw every
	// subscription model as having free cache (a real D.AI model showed
	// 0.002 / 0.02 here and 0 / 0 in the price panel). Send both shapes.
	if (cacheRead !== undefined || cacheWrite !== undefined) {
		cost.cache = {};
		if (cacheRead !== undefined) cost.cache.read = cacheRead;
		if (cacheWrite !== undefined) cost.cache.write = cacheWrite;
	}
	// magpie only marks a model free when it carries `free: true`; it never
	// infers that from a zero price. D.AI prices a free model at exactly $0 on
	// every rate, so that is the condition (a null cache rate is billed at the
	// input rate, which is 0 here too).
	const free = cost.input === 0 && cost.output === 0 && (cost.cache_read ?? 0) === 0 && (cost.cache_write ?? 0) === 0;
	return {
		id,
		name: id,
		// Magpie's model parser reads these top-level fields. Keep
		// capabilities as well for OpenCode readers that use that shape.
		reasoning: Boolean(variants),
		attachment: vision,
		tool_call: true,
		api: { id, npm, url: apiBase(base) },
		provider: { npm, api: apiBase(base) },
		limit: {
			context: Math.max(1, numberOr(rate.context_window_tokens, 128_000)),
			output: Math.max(1, numberOr(rate.prepay_completion_token_limit, 128_000)),
		},
		capabilities: {
			reasoning: Boolean(variants),
			toolcall: true,
			attachment: vision,
			input: vision ? { text: true, image: true } : { text: true },
		},
		modalities: { input: vision ? ["text", "image"] : ["text"] },
		cost,
		...(free ? { free: true } : {}),
		...(variants ? { variants } : {}),
	};
}

/**
 * Claude settlement ignores D.AI's published cache rates and weights cached
 * tokens against the input rate, matching sdks/pi/src/discover.ts.
 */
function cacheRate(id, rate) {
	const published = positiveNumber(rate.billing_rules?.cache_read_usd_per_1m_tokens);
	if (!isClaudeModel(id)) return published;
	const input = numberOr(rate.input_usd_per_1m_tokens, 0);
	return (input * 2) / 20;
}

function fallbackCatalog(base) {
	const models = {};
	for (const [id, context, output, input, out, cacheRead] of FALLBACK_ROWS) {
		models[id] = buildModel(id, base, {
			context_window_tokens: context,
			prepay_completion_token_limit: output,
			input_usd_per_1m_tokens: input,
			output_usd_per_1m_tokens: out,
			billing_rules: { cache_read_usd_per_1m_tokens: cacheRead },
		});
	}
	for (const [id, name] of FALLBACK_DECISIONS) {
		models[id] = buildDecisionModel(id, name, base);
	}
	return models;
}

/**
 * A decision model: it answers System One's questions and never a
 * conversation, which is what `decides` says. Its price is per request, not
 * per token, so it carries no `cost` at all rather than a token rate of $0
 * that magpie would read as free.
 */
function buildDecisionModel(id, name, base) {
	return {
		id,
		name: textOf(name) || id,
		api: { id, npm: OPENAI_NPM, url: apiBase(base) },
		provider: { npm: OPENAI_NPM, api: apiBase(base) },
		decides: true,
		reasoning: false,
		attachment: false,
		tool_call: false,
		capabilities: {
			reasoning: false,
			toolcall: false,
			attachment: false,
			input: { text: true },
		},
		modalities: { input: ["text"], output: ["text"] },
	};
}

/**
 * An image model: it draws on D.AI's OpenAI Images API and answers with an
 * image alone, which is what makes magpie list it under the provider's image
 * models and send a drawing there rather than a chat. Its price is per image,
 * so it carries no token cost magpie could read as free.
 */
function buildImageModel(id, base, model = {}) {
	return buildMediaModel(id, base, model, "image");
}

/**
 * A video model: it answers with a video alone, which is what makes magpie
 * list it under the provider's video models and send an OpenAI-shaped video
 * request there rather than a chat.
 */
function buildVideoModel(id, base, model = {}) {
	return buildMediaModel(id, base, model, "video");
}

/** A model that makes one kind of media and talks no chat. */
function buildMediaModel(id, base, model, kind) {
	return {
		id,
		name: textOf(model?.display_name) || id,
		api: { id, npm: OPENAI_NPM, url: apiBase(base) },
		provider: { npm: OPENAI_NPM, api: apiBase(base) },
		reasoning: false,
		attachment: false,
		tool_call: false,
		capabilities: {
			reasoning: false,
			toolcall: false,
			attachment: false,
			input: { text: true },
			output: { [kind]: true },
		},
		modalities: { input: ["text"], output: [kind] },
	};
}

/**
 * magpie's own address for this provider, as D.AI serves it, or undefined for
 * every other request.
 */
function daiPath(input, base) {
	const raw =
		typeof input === "string" ? input : input instanceof URL ? input.href : textOf(input?.url);
	if (!raw) return undefined;
	let url;
	try {
		url = new URL(raw);
	} catch {
		return undefined;
	}
	for (const [from, to] of DAI_PATHS) {
		if (url.pathname.endsWith(from)) return `${base}${to}${url.search}`;
	}
	return undefined;
}

