// ---- OAuth ---------------------------------------------------------------------

function pkcePair() {
	const verifier = randomBytes(32).toString("base64url");
	const challenge = createHash("sha256").update(verifier).digest("base64url");
	return { verifier, challenge };
}

function oauthForm(values) {
	const body = new URLSearchParams();
	for (const [key, value] of Object.entries(values)) {
		if (value !== undefined && value !== null && String(value) !== "") {
			body.set(key, String(value));
		}
	}
	return body;
}

async function tokenRequest(base, values, signal) {
	const res = await fetch(`${base}/api/oauth/token`, {
		method: "POST",
		headers: {
			"content-type": "application/x-www-form-urlencoded",
			accept: "application/json",
			"x-dai-client": CLIENT,
		},
		body: oauthForm(values),
		signal: signal
			? AbortSignal.any([signal, AbortSignal.timeout(REQUEST_TIMEOUT_MS)])
			: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
	});
	const payload = await res.json().catch(() => null);
	if (!res.ok) {
		return {
			status: res.status,
			error: textOf(payload?.error),
			description: textOf(payload?.error_description),
		};
	}
	return payload ?? {};
}

/**
 * A loopback callback for one OAuth sign-in. Binding to port 0 keeps the
 * callback flexible without reserving a fixed port on the user's Mac.
 */
function callbackServer() {
	return new Promise((resolve, reject) => {
		const server = createServer();
		const sockets = new Set();
		const waiters = new Set();
		let accepted = false;
		let settled = false;
		let closed = false;
		const settle = (query) => {
			if (settled) return false;
			settled = true;
			for (const waiter of waiters) waiter(query);
			waiters.clear();
			return true;
		};
		const close = () => {
			if (closed) return;
			closed = true;
			server.close(() => {
				for (const socket of sockets) socket.destroy();
			});
		};
		server.on("connection", (socket) => {
			sockets.add(socket);
			socket.on("close", () => sockets.delete(socket));
		});
		server.on("error", reject);
		server.on("request", (req, res) => {
			const url = new URL(req.url ?? "/", "http://127.0.0.1");
			if (url.pathname !== OAUTH_CALLBACK_PATH) {
				res.writeHead(404, { "content-type": "text/plain; charset=utf-8" });
				res.end("not found");
				return;
			}
			if (accepted) {
				res.writeHead(409, { "content-type": "text/plain; charset=utf-8" });
				res.end("callback already received");
				return;
			}
			accepted = true;
			res.writeHead(200, {
				"content-type": "text/html; charset=utf-8",
				"cache-control": "no-store",
			});
			res.end(
				'<!doctype html><meta charset="utf-8"><title>D.AI 回调</title><p>回调已收到，请返回 Magpie 查看结果。</p>',
				() => {
					settle(url.searchParams);
					close();
				},
			);
		});
		server.listen(0, "127.0.0.1", () => {
			const address = server.address();
			if (!address || typeof address === "string") {
				server.close();
				reject(new Error("无法创建 D.AI 本地回调"));
				return;
			}
			const redirectUri = `http://127.0.0.1:${address.port}${OAUTH_CALLBACK_PATH}`;
			resolve({
				redirectUri,
				wait({ signal, timeoutMs = OAUTH_SIGN_IN_TIMEOUT_MS } = {}) {
					return new Promise((done, fail) => {
						if (signal?.aborted) {
							close();
							fail(new Error("D.AI 登录已取消"));
							return;
						}
						let finished = false;
						let timer;
						const cleanup = () => {
							if (timer) clearTimeout(timer);
							waiters.delete(waiter);
							signal?.removeEventListener("abort", onAbort);
						};
						const finish = (ok, value) => {
							if (finished) return;
							finished = true;
							cleanup();
							if (ok) done(value);
							else fail(value);
						};
						const onAbort = () => {
							close();
							finish(false, new Error("D.AI 登录已取消"));
						};
						const waiter = (query) => {
							finish(true, { query });
						};
						waiters.add(waiter);
						timer = setTimeout(() => {
							close();
							finish(false, new Error("D.AI 登录超时，请重新登录"));
						}, timeoutMs);
						signal?.addEventListener("abort", onAbort, { once: true });
					});
				},
				close,
			});
		});
	});
}

/** Browser sign-in: authorization code + PKCE, callback owned by the plugin. */
async function browserSignIn(base, clientId = OAUTH_CLIENT_ID) {
	const { verifier, challenge } = pkcePair();
	const state = randomBytes(16).toString("base64url");
	const nonce = randomBytes(16).toString("base64url");
	const callback = await callbackServer();
	const authorize = new URL(`${base}/api/oauth/authorize`);
	authorize.searchParams.set("client_id", clientId);
	authorize.searchParams.set("redirect_uri", callback.redirectUri);
	authorize.searchParams.set("response_type", "code");
	authorize.searchParams.set("scope", OAUTH_SCOPES);
	authorize.searchParams.set("state", state);
	authorize.searchParams.set("nonce", nonce);
	authorize.searchParams.set("code_challenge", challenge);
	authorize.searchParams.set("code_challenge_method", "S256");
	return {
		url: authorize.toString(),
		instructions: "在浏览器中登录 D.AI 并同意授权；完成后会自动回到 Magpie。",
		method: "auto",
		async callback({ signal, timeoutMs = OAUTH_SIGN_IN_TIMEOUT_MS } = {}) {
			try {
				const { query } = await callback.wait({ signal, timeoutMs });
				if (textOf(query.get("state")) !== state) {
					return { type: "failed", error: "D.AI 登录状态校验失败" };
				}
				const error = textOf(query.get("error"));
				if (error) {
					return {
						type: "failed",
						error: textOf(query.get("error_description")) || `D.AI 登录失败：${error}`,
					};
				}
				const code = textOf(query.get("code"));
				if (!code) return { type: "failed", error: "D.AI 没有返回授权码" };
				const token = await tokenRequest(
					base,
					{
						grant_type: "authorization_code",
						client_id: clientId,
						code,
						redirect_uri: callback.redirectUri,
						code_verifier: verifier,
					},
					signal,
				);
				if (!token.access_token) {
					return {
						type: "failed",
						error:
							token.description ||
							token.error ||
							`D.AI 换取令牌失败（HTTP ${token.status ?? "?"}）`,
					};
				}
				const who = await fetchJson(`${base}/api/oauth/userinfo`, {
					apiKey: token.access_token,
					oauth: true,
				}).catch(() => null);
				const accountId =
					textOf(who?.email) || textOf(who?.preferred_username) || textOf(who?.sub);
				return {
					type: "success",
					access: token.access_token,
					refresh: token.refresh_token ?? "",
					expires: Date.now() + numberOr(token.expires_in, 3600) * 1000,
					...(accountId ? { accountId } : {}),
					...(textOf(who?.sub) ? { uid: textOf(who.sub) } : {}),
				};
			} catch (error) {
				return { type: "failed", error: String(error?.message ?? error) };
			} finally {
				callback.close();
			}
		},
	};
}

async function refreshOAuth(base, auth, clientId = OAUTH_CLIENT_ID) {
	if (!isOAuthAuth(auth)) return;
	const refresh = textOf(auth?.refresh);
	if (!refresh) throw Object.assign(new Error("D.AI 登录已失效"), { signIn: "expired" });
	const token = await tokenRequest(base, {
		grant_type: "refresh_token",
		client_id: clientId,
		refresh_token: refresh,
	});
	if (!token.access_token) {
		const expired =
			token.status === 400 ||
			token.error === "invalid_grant" ||
			token.error === "invalid_refresh_token";
		throw Object.assign(
			new Error(token.description || token.error || "D.AI 刷新登录失败"),
			expired ? { signIn: "expired" } : {},
		);
	}
	return {
		access: token.access_token,
		refresh: token.refresh_token ?? refresh,
		expires: Date.now() + numberOr(token.expires_in, 3600) * 1000,
	};
}

