function mediaLimit(input = {}) {
	return Math.max(
		1,
		Math.min(100, Math.floor(optionalNumber(input.limit) ?? MEDIA_CATALOG_LIMIT)),
	);
}

function mediaMatches(rows, input = {}) {
	const kind = textOf(input.kind).toLowerCase();
	if (kind && !MEDIA_KINDS.has(kind)) {
		throw new Error("media_catalog kind must be image, video or audio");
	}
	const capability = textOf(input.capabilityCode).toLowerCase();
	const model = textOf(input.model).toLowerCase();
	const service = textOf(input.serviceCode).toLowerCase();
	const terms = textOf(input.query).toLowerCase().split(/\s+/u).filter(Boolean);
	return rows
		.filter((row) => !kind || row.kind === kind)
		.filter((row) => !capability || row.capabilityCode.toLowerCase() === capability)
		.filter((row) => !model || row.modelCode.toLowerCase() === model)
		.filter((row) => !service || row.serviceCode.toLowerCase() === service)
		.filter((row) => {
			if (!terms.length) return true;
			const haystack = [
				row.modelCode,
				row.serviceCode,
				row.capabilityCode,
				row.capabilityName,
				row.displayName,
				row.description,
			]
				.join(" ")
				.toLowerCase();
			return terms.every((term) => haystack.includes(term));
		});
}

function filterMedia(rows, input = {}) {
	return mediaMatches(rows, input).slice(0, mediaLimit(input));
}

async function mediaCatalog(base, input, signal) {
	const catalog = await fetchGatewayModels(base, signal);
	const matches = mediaMatches(mediaRows(catalog), input);
	const models = matches.slice(0, mediaLimit(input)).map(mediaModel);
	return { models, count: models.length, matched: matches.length };
}

