const DaiPlugin = async (_input, options = {}) => {
	const base = normalizeBase(options?.baseUrl ?? process.env.DAI_BASE_URL) ?? DEFAULT_BASE;
	const oauthClientId = textOf(options?.oauthClientId) || OAUTH_CLIENT_ID;
	const offline = fallbackCatalog(base);

	// One catalog read per account, reused until it goes stale. Keyed by the
	// API key, never module-global: magpie runs every account of a provider
	// through this one plugin instance.
	const catalogs = new Map();
	const catalogFor = async (key, signal) => {
		const cached = catalogs.get(key);
		if (cached && Date.now() - cached.at < CATALOG_TTL_MS) return cached.models;
		const models = await fetchCatalog(base, { key, signal });
		if (Object.keys(models).length) {
			catalogs.set(key, { at: Date.now(), models });
			return models;
		}
		return undefined;
	};

	return {
		// Declare the provider so it exists before anyone signs in; `??=` keeps
		// whatever the user configured for it in plugins.json.
		config: async (cfg) => {
			cfg.provider ??= {};
			const provider = (cfg.provider[PROVIDER] ??= {
				name: "D.AI",
				npm: OPENAI_NPM,
				api: apiBase(base),
				models: offline,
			});
			// magpie posts questions to a provider that serves a decision API,
			// at its base /systemone, and hides the models marked `decides`
			// from agents. Both marks are needed for Jev to be usable.
			provider.decide = true;
			provider.models ??= {};
			for (const [id, name] of FALLBACK_DECISIONS) {
				provider.models[id] ??= buildDecisionModel(id, name, base);
			}
		},

		auth: {
			provider: PROVIDER,

			refreshLead: 5 * 60 * 1000,

			async refresh(auth) {
				return refreshOAuth(base, auth, oauthClientId);
			},

			methods: [
				{
					type: "oauth",
					label: "使用 D.AI 账号登录",
					authorize: () => browserSignIn(base, oauthClientId),
				},
				{ type: "api", label: "D.AI API 密钥", placeholder: "ddsk_…" },
			],

			async loader(getAuth) {
				const auth = await getAuth();
				const credential = credentialOf(auth);
				if (!credential) return {};
				return {
					baseURL: apiBase(base),
					apiKey: credential,
					headers: { "x-dai-client": CLIENT },
					fetch: daiFetch(base, credential, isOAuthAuth(auth)),
				};
			},

			// The account behind either sign-in: wallet balance, tier and token
			// totals from `GET /api/ai/account`. The card says the balance as the
			// wallet's total, then what this key may spend and what it has used.
			async usage(getAuth) {
				const auth = await getAuth();
				const credential = credentialOf(auth);
				if (!credential) {
					return { windows: [], error: "D.AI：请先登录" };
				}
				try {
					const account = await fetchJson(`${base}/api/ai/account`, {
						apiKey: credential,
						oauth: isOAuthAuth(auth),
					});
					return balanceCard(account, authLabel(auth));
				} catch (error) {
					const status = error?.status;
					if (status === 401 || status === 403) {
						return { windows: [], error: "D.AI 登录已失效", signIn: "expired" };
					}
					// A deployment older than the endpoint answers 404. Its call log
					// is still there, and counting calls beats showing an error.
					if (status === 404 && !isOAuthAuth(auth)) {
						try {
							return await callLogCard(base, credential);
						} catch (fallbackError) {
							return { windows: [], error: String(fallbackError?.message ?? fallbackError) };
						}
					}
					return { windows: [], error: String(error?.message ?? error) };
				}
			},
		},

		provider: {
			id: PROVIDER,

			// The account's own list when D.AI answers, else the catalog the
			// config hook declared, so a failed fetch never empties the provider.
			async models(provider, { auth } = {}) {
				const credential = credentialOf(auth);
				if (!credential) return provider.models;
				try {
					const models = await catalogFor(credential, undefined);
					return models ?? provider.models;
				} catch (error) {
					if (error?.signIn === "expired") throw error;
					return provider.models;
				}
			},
		},

		"chat.headers": async (input, output) => {
			if (input?.model?.providerID !== PROVIDER) return;
			const session = textOf(input?.sessionID);
			if (session) output.headers["x-dai-session"] = session;
		},

		tool: {
			media_catalog: {
				description:
					"List D.AI image, video and audio models published by the public generation gateway. Read-only and free. Returns submit and fetch paths, parameters and tier prices; generation requires a separately authenticated tool.",
				args: {
					type: "object",
					properties: {
						kind: {
							type: "string",
							enum: ["image", "video", "audio"],
							description: "Optional capability type.",
						},
						capabilityCode: {
							type: "string",
							description: "Exact capability code, such as openai_image or gemini_video.",
						},
						model: {
							type: "string",
							description: "Exact model code, such as gpt-image-2.5-flare.",
						},
						serviceCode: {
							type: "string",
							description: "Exact operation code when one model has several, such as midjourney_imagine.",
						},
						query: {
							type: "string",
							description: "Case-insensitive search in model, service, capability and description text.",
						},
						limit: {
							type: "integer",
							minimum: 1,
							maximum: 100,
							default: 20,
							description: "Maximum number of models to return.",
						},
					},
					additionalProperties: false,
				},
				async execute(input, ctx) {
					return mediaCatalog(base, input, ctx?.abort);
				},
			},
		},
	};
};

